/// One picture to trace, as the template list shows it.
struct TemplateDesign: Equatable, Identifiable {
    /// Stored with saved paintings, so it never changes.
    let id: String
    let title: String
    /// 1 = easy … 4 = hardest: more lines, spread further over the canvas, so the arms reach further.
    let level: Int
    let art: OutlineArt
}

